SELECT result_tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (SELECT lhs.original_group AS result_tags, lhs.timestamp AS timestamp, lhs.value AS value FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, d.value AS value FROM (SELECT grid_base.id AS id, grid_base.tags AS tags, grid_base.eval_ts AS eval_ts, grid_base.eval_ts - toIntervalMillisecond({lhs_offset_ms:Int64}) AS eval_bound FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({lhs_start_ms:Int64}, {lhs_end_ms:Int64} + {lhs_step_ms:Int64}, {lhs_step_ms:Int64}))) AS eval_ts FROM (
            SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {lhs_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64})
        ) AS series) AS grid_base) AS grid ASOF INNER JOIN (
            SELECT id, timestamp, value FROM timeSeriesData(`observability`.`prometheus`) WHERE timestamp >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND timestamp <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64}) AND id IN (SELECT DISTINCT src.id FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {lhs_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64}))
        ) AS d ON grid.id = d.id AND grid.eval_bound >= d.timestamp WHERE d.timestamp >= grid.eval_ts - toIntervalMillisecond({lhs_offset_ms:Int64} + {lhs_lookback_ms:Int64}) AND NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) ARRAY JOIN time_series AS point)) AS lhs UNION ALL SELECT rhs.original_group AS result_tags, rhs.timestamp AS timestamp, rhs.value AS value FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, d.value AS value FROM (SELECT grid_base.id AS id, grid_base.tags AS tags, grid_base.eval_ts AS eval_ts, grid_base.eval_ts - toIntervalMillisecond({rhs_offset_ms:Int64}) AS eval_bound FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({rhs_start_ms:Int64}, {rhs_end_ms:Int64} + {rhs_step_ms:Int64}, {rhs_step_ms:Int64}))) AS eval_ts FROM (
            SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {rhs_range_instant_matcher_0_value:String} AND src.tags[concat('', {rhs_range_instant_matcher_1_key:String})] = {rhs_range_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64})
        ) AS series) AS grid_base) AS grid ASOF INNER JOIN (
            SELECT id, timestamp, value FROM timeSeriesData(`observability`.`prometheus`) WHERE timestamp >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND timestamp <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64}) AND id IN (SELECT DISTINCT src.id FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {rhs_range_instant_matcher_0_value:String} AND src.tags[concat('', {rhs_range_instant_matcher_1_key:String})] = {rhs_range_instant_matcher_1_value:String} AND src.max_time >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64}))
        ) AS d ON grid.id = d.id AND grid.eval_bound >= d.timestamp WHERE d.timestamp >= grid.eval_ts - toIntervalMillisecond({rhs_offset_ms:Int64} + {rhs_lookback_ms:Int64}) AND NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) ARRAY JOIN time_series AS point)) AS rhs LEFT JOIN (SELECT join_group, timestamp, toUInt8(1) AS present_marker FROM (SELECT tags AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, value AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, d.value AS value FROM (SELECT grid_base.id AS id, grid_base.tags AS tags, grid_base.eval_ts AS eval_ts, grid_base.eval_ts - toIntervalMillisecond({lhs_offset_ms:Int64}) AS eval_bound FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({lhs_start_ms:Int64}, {lhs_end_ms:Int64} + {lhs_step_ms:Int64}, {lhs_step_ms:Int64}))) AS eval_ts FROM (
            SELECT DISTINCT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {lhs_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64})
        ) AS series) AS grid_base) AS grid ASOF INNER JOIN (
            SELECT id, timestamp, value FROM timeSeriesData(`observability`.`prometheus`) WHERE timestamp >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND timestamp <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64}) AND id IN (SELECT DISTINCT src.id FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {lhs_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64}))
        ) AS d ON grid.id = d.id AND grid.eval_bound >= d.timestamp WHERE d.timestamp >= grid.eval_ts - toIntervalMillisecond({lhs_offset_ms:Int64} + {lhs_lookback_ms:Int64}) AND NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) ARRAY JOIN time_series AS point)) AS lhs GROUP BY join_group, timestamp) AS lhs ON lhs.join_group = rhs.join_group AND lhs.timestamp = rhs.timestamp WHERE ifNull(lhs.present_marker, 0) = 0) AS joined_rows GROUP BY result_tags ORDER BY result_tags
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
